#include <stdio.h>
int main() {
  int x = 5;
  int *p = &x;
  *p = 10;
  printf("x=%d p=%p\n", x, (void*)p);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main() {
  int *arr = malloc(3 * sizeof(int));
  if (!arr) return 1;
  arr[0] = 1; arr[1] = 2; arr[2] = 3;
  printf("arr=%p arr[0]=%d\n", (void*)arr, arr[0]);
  free(arr);
  return 0;
}
